module old021::resources;
pub server resource Session;
pub server resource Buffer<T>;
server fn forward(x:Buffer<i64>)->Buffer<i64>{return x;}
fn answer()->i64{return 42;}
fn main()->unit !{io}{print(answer());}
test fn retained_answer()->unit{assert(answer()==42);}

